  'hist.payable':        { en: 'Tax Payable',    hi: 'देय कर' , bn: 'প্রদেয় কর', or: 'ପ୍ରଦେୟ ଆୟକର', ta: 'செலுத்த வேண்டிய வரி', te: 'చెల్లించవలసిన పన్ను' },
