  'hist.mf':             { en: 'MF Equity Tax',  hi: 'म्यूचुअल फंड कर' , bn: 'মিউচুয়াল ফান্ড কর', or: 'ମ୍ୟୁଚୁଆଲ ଫଣ୍ଡ ଆୟକର', ta: 'மியூச்சுவல் ஃபண்ட் வரி', te: 'మ్యూచువల్ ఫండ్ పన్ను' },
  'hist.view':           { en: 'View Details',   hi: 'विवरण देखें' , bn: 'বিস্তারিত দেখুন', or: 'ବିବରଣ ଦେଖନ୍ତୁ', ta: 'விவரங்களை பாருங்கள்', te: 'వివరాలు చూడండి' },
