const LanguageContext = createContext<LanguageContextValue | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [lang, setLang] = useState<Language>(() =>
    (localStorage.getItem('smarttax_lang') as Language) ?? 'en'
  );

  useEffect(() => {
    localStorage.setItem('smarttax_lang', lang);
  }, [lang]);

  const LANG_CYCLE: Language[] = ['en', 'hi', 'bn', 'or', 'ta', 'te'];
  const toggleLang = () => setLang(prev => { const i = LANG_CYCLE.indexOf(prev); return LANG_CYCLE[(i + 1) % LANG_CYCLE.length]; });

  const t = (key: string): string => T[key]?.[lang] ?? T[key]?.['en'] ?? key;

  return (
    <LanguageContext.Provider value={{ lang, toggleLang, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLang = (): LanguageContextValue => {
  const ctx = useContext(LanguageContext);
  if (!ctx) throw new Error('useLang must be used inside LanguageProvider');
  return ctx;
};
